import React, { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import axios from 'axios';
import { Container, Row, Col, Card, Form, Button, Alert } from 'react-bootstrap';

const Makepayment = () => {
  const navigate = useNavigate();
  const location = useLocation();
  
  // Get cart data from navigation state
  const { cartItems = [], totalAmount = 0 } = location.state || {};
  
  const [phone, setPhone] = useState('');
  const [loading, setLoading] = useState(false);
  const [success, setSuccess] = useState('');
  const [error, setError] = useState('');

  const payNow = async (e) => {
    e.preventDefault();
    if (!phone || phone.length < 10) {
      setError('Please enter a valid phone number (e.g., 2547XXXXXXX)');
      return;
    }

    setLoading(true);
    setError('');

    try {
      const response = await axios.post('https://sengi2025.pythonanywhere.com/api/mpesa_payment', {
        amount: totalAmount,
        phone: phone,
      });

      setSuccess(response.data.message || 'Payment initiated successfully!');
      setPhone('');

      setTimeout(() => {
        navigate('/checkout', { state: { cartItems, totalAmount } });
      }, 3000);

    } catch (err) {
      setError('Payment failed. Please try again later.');
      console.error('Payment error:', err.response?.data || err.message);
    } finally {
      setLoading(false);
    }
  };

  if (cartItems.length === 0) {
    return (
      <Container className="text-center py-5">
        <Alert variant="danger" className="shadow-sm">
          <h2>Your cart is empty</h2>
          <p>Please add some products to your cart first</p>
          <Button 
            variant="primary" 
            onClick={() => navigate('/shop')}
            className="mt-3"
          >
            Back to Shop
          </Button>
        </Alert>
      </Container>
    );
  }

  return (
    <Container className="py-5">
      <Row className="justify-content-center">
        <Col lg={8}>
          <Card className="border-0 shadow rounded-4">
            <Card.Header className="bg-primary text-white">
              <h2 className="mb-0">Complete Your Purchase</h2>
            </Card.Header>
            
            <Card.Body>
              <Row>
                <Col md={6}>
                  <Card className="border-0">
                    <Card.Body>
                      <h4 className="text-info mb-3">Order Summary</h4>
                      {cartItems.map((item, index) => (
                        <div key={index} className="mb-3 border-bottom pb-3">
                          <div className="d-flex align-items-center">
                            <div className="bg-light rounded me-3" style={{ width: '60px', height: '60px' }}>
                              <i className="bi bi-fish h-100 d-flex align-items-center justify-content-center fs-3 text-primary"></i>
                            </div>
                            <div>
                              <h6 className="mb-0">{item.name}</h6>
                              <p className="text-muted mb-0">
                                {item.quantity} kg × KES {item.price.toFixed(2)}
                              </p>
                              <p className="fw-bold mt-1">
                                KES {(item.price * item.quantity).toFixed(2)}
                              </p>
                            </div>
                          </div>
                        </div>
                      ))}
                      
                      <div className="d-flex justify-content-between mt-4">
                        <h5>Total:</h5>
                        <h4 className="text-success">KES {totalAmount}</h4>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
                
                <Col md={6}>
                  <Card className="border-0 mt-3 mt-md-0">
                    <Card.Body>
                      <h4 className="text-success mb-4">Lipa na M-PESA</h4>
                      
                      {success && (
                        <Alert variant="success" className="mb-4">
                          {success}
                        </Alert>
                      )}
                      
                      {error && (
                        <Alert variant="danger" className="mb-4">
                          {error}
                        </Alert>
                      )}
                      
                      <Form onSubmit={payNow}>
                        <Form.Group className="mb-3">
                          <Form.Label>Amount to Pay</Form.Label>
                          <Form.Control 
                            type="text" 
                            value={`KES ${totalAmount}`} 
                            readOnly 
                            className="fw-bold fs-5"
                          />
                        </Form.Group>
                        
                        <Form.Group className="mb-3">
                          <Form.Label>Phone Number</Form.Label>
                          <Form.Control 
                            type="tel"
                            placeholder="2547XXXXXXXX"
                            value={phone}
                            onChange={(e) => setPhone(e.target.value)}
                            required
                          />
                          <Form.Text className="text-muted">
                            Format: 2547XXXXXXXX
                          </Form.Text>
                        </Form.Group>
                        
                        <Button 
                          variant="success" 
                          type="submit"
                          className="w-100 py-2"
                          disabled={loading}
                        >
                          {loading ? (
                            <>
                              <span className="spinner-border spinner-border-sm me-2"></span>
                              Processing Payment...
                            </>
                          ) : (
                            <>
                              <i className="bi bi-lock-fill me-2"></i>
                              Pay Now
                            </>
                          )}
                        </Button>
                      </Form>
                      
                      <div className="mt-4 text-center">
                        <img 
                    
                         
                        />
                        <p className="text-muted small">
                          You'll receive a payment request on your phone
                        </p>
                      </div>
                    </Card.Body>
                  </Card>
                </Col>
              </Row>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default Makepayment;
